// MUTANT COPY - NOT the design under test. Do not edit this file to fix a
// bug; edit rtl/daq_top.sv and re-copy, then re-apply the two `ifdef blocks
// below (search for MUTANT_).
//
// Two independently selectable defects, used to answer "can these formal
// properties actually fail?". Module names are unchanged so it is a drop-in
// replacement for the real file.
//
//   +define+MUTANT_FIFO_FULL_STUCK_LOW
//       w_full is tied to 0, so the async FIFO never reports full and
//       silently overwrites entries that have not been read yet.
//       Expected to break daq_fifo.sby: occupancy bound, the "w_full is never
//       optimistic" property, and the no-silent-overflow property.
//
//   +define+MUTANT_POP_IGNORES_READY
//       The FIFO is popped on dma_wvalid alone instead of on the accepted
//       beat, so a stalled memory silently loses data - exactly the bug the
//       backpressure work exists to prevent.
//       Expected to break daq_status*.sby: no-pop-without-ready and the
//       stalled-request stability property.
//
// Run with formal\daq_fifo_MUTANT.sby and formal\daq_status_sync_MUTANT.sby,
// or run_formal.ps1 -Mutant. Both are expected to FAIL; a PASS means the
// properties are vacuous.
//
// ---------------------------------------------------------------------------
// Data acquisition subsystem.
//
// Three clock domains:
//   ctrl_clk  CSR register file (read and write)
//   src_clk   packet source stream
//   dma_clk   DMA write engine, target memory, interrupt state
//
// Packet format on the source stream: sop on the first payload byte, payload
// bytes, then one final beat with eop=1 carrying the CRC-8 of every preceding
// payload byte. The CRC beat is consumed internally and never written to
// memory, so memory receives payload only.
//
// Register map (ctrl_clk domain, 4-bit address):
//   0  CTRL       RW  [0] enable  [1] crc_inject  [2] bad_irq_demo
//   1  CMD        WO  [0] clear - aborts the transfer and clears status
//   2  INTR_EN    RW  [3:0] done, crc_error, bus_error, fifo_overflow
//   3  INTR_STATE W1C [3:0] same bit order; writing 1 clears that bit only
//   4  STATUS     RO  [0] busy  [15:8] byte_count of the last completed transfer
//   5  ID         RO  constant, for readback sanity
//
// Every crossing between domains is explicit: single sticky bits use two-flop
// synchronizers, and anything multi-bit uses a data+toggle handshake so the
// payload is stable before the receiver is told to look at it. The raw FSM
// encoding is deliberately NOT exposed in the register map - a 3-bit state
// cannot cross a clock boundary coherently without its own handshake, and a
// debug register is not worth one, so STATUS exposes a single `busy` bit
// instead.
module daq_async_fifo #(parameter int DEPTH=8) (
  input logic wclk, wrst_n, w_en, input logic [9:0] wdata, output logic w_full,
  input logic rclk, rrst_n, r_en, output logic [9:0] rdata, output logic r_empty
);
  localparam int AW=$clog2(DEPTH);
  logic [9:0] mem[0:DEPTH-1];
  logic [AW:0] wbin, wgray, rbin, rgray, wbin_n, wgray_n, rbin_n, rgray_n;
  logic [AW:0] rgray_w1, rgray_w2, wgray_r1, wgray_r2;
  logic wfull_n, rempty_n;
  function automatic [AW:0] bin2gray(input [AW:0] b); bin2gray=(b>>1)^b; endfunction
  assign wbin_n=wbin+(w_en && !w_full); assign wgray_n=bin2gray(wbin_n);
  assign rbin_n=rbin+(r_en && !r_empty); assign rgray_n=bin2gray(rbin_n);
  assign wfull_n=(wgray_n=={~rgray_w2[AW:AW-1],rgray_w2[AW-2:0]});
  assign rempty_n=(rgray_n==wgray_r2);
  assign rdata=mem[rbin[AW-1:0]];
  always_ff @(posedge wclk or negedge wrst_n) begin
    if(!wrst_n) begin wbin<='0; wgray<='0; w_full<=0; rgray_w1<='0; rgray_w2<='0; end
`ifdef MUTANT_FIFO_FULL_STUCK_LOW
    else begin rgray_w1<=rgray; rgray_w2<=rgray_w1; if(w_en && !w_full) mem[wbin[AW-1:0]]<=wdata; wbin<=wbin_n; wgray<=wgray_n; w_full<=1'b0; end
`else
    else begin rgray_w1<=rgray; rgray_w2<=rgray_w1; if(w_en && !w_full) mem[wbin[AW-1:0]]<=wdata; wbin<=wbin_n; wgray<=wgray_n; w_full<=wfull_n; end
`endif
  end
  always_ff @(posedge rclk or negedge rrst_n) begin
    if(!rrst_n) begin rbin<='0; rgray<='0; r_empty<=1; wgray_r1<='0; wgray_r2<='0; end
    else begin wgray_r1<=wgray; wgray_r2<=wgray_r1; rbin<=rbin_n; rgray<=rgray_n; r_empty<=rempty_n; end
  end
endmodule

module daq_top(
  input  logic ctrl_clk, src_clk, dma_clk, rst_n,
  // CSR, ctrl_clk domain
  input  logic        csr_we, csr_re,
  input  logic [3:0]  csr_addr,
  input  logic [31:0] csr_wdata,
  output logic [31:0] csr_rdata,
  // packet source, src_clk domain
  input  logic src_valid, output logic src_ready,
  input  logic src_sop, src_eop, input logic [7:0] src_data,
  // DMA write port, dma_clk domain. AXI-style valid/ready with a write
  // response on the accepted beat.
  input  logic dma_wready, dma_wresp_err,
  output logic dma_wvalid, output logic [3:0] dma_waddr, output logic [7:0] dma_wdata,
  // observation outputs for the testbench and formal harnesses
  output logic irq, done, crc_error, bus_error, fifo_overflow,
  output logic [7:0] mem0, mem1, mem2, mem3
);
  // ---------------------------------------------------------------------
  // Register addresses and interrupt bit positions
  // ---------------------------------------------------------------------
  localparam logic [3:0] A_CTRL=4'd0, A_CMD=4'd1, A_INTR_EN=4'd2, A_INTR_STATE=4'd3,
                         A_STATUS=4'd4, A_ID=4'd5;
  localparam int I_DONE=0, I_CRC=1, I_BUS=2, I_OVF=3;
  localparam logic [31:0] ID_VALUE = 32'h0DA0_0001;

  // ---------------------------------------------------------------------
  // ctrl_clk domain: register file
  // ---------------------------------------------------------------------
  logic enable_ctrl, inject_ctrl, bad_irq_ctrl;
  logic [3:0] intr_en_ctrl;
  logic [3:0] w1c_mask_ctrl;
  logic       w1c_tgl_ctrl, cmd_tgl_ctrl;

  always_ff @(posedge ctrl_clk or negedge rst_n) begin
    if (!rst_n) begin
      enable_ctrl<=0; inject_ctrl<=0; bad_irq_ctrl<=0; intr_en_ctrl<='0;
      w1c_mask_ctrl<='0; w1c_tgl_ctrl<=0; cmd_tgl_ctrl<=0;
    end else if (csr_we) begin
      case (csr_addr)
        A_CTRL:    begin enable_ctrl<=csr_wdata[0]; inject_ctrl<=csr_wdata[1]; bad_irq_ctrl<=csr_wdata[2]; end
        A_INTR_EN: intr_en_ctrl<=csr_wdata[3:0];
        // Both of these cross into dma_clk. The payload is written first and
        // the toggle flips in the same cycle, so by the time the receiver sees
        // the toggle edge (two synchronizer flops later) the payload has been
        // stable for at least two dma_clk edges.
        A_INTR_STATE: begin w1c_mask_ctrl<=csr_wdata[3:0]; w1c_tgl_ctrl<=~w1c_tgl_ctrl; end
        A_CMD:     if (csr_wdata[0]) cmd_tgl_ctrl<=~cmd_tgl_ctrl;
        default: ;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // ctrl_clk <- dma_clk readback
  // ---------------------------------------------------------------------
  logic [3:0] intr_state_c1, intr_state_c2;  // per-bit, sticky, safe to sync directly
  logic       busy_c1, busy_c2;
  logic       bc_tgl_c1, bc_tgl_c2, bc_tgl_c3;
  logic [7:0] byte_count_ctrl;
  logic [3:0] intr_state;
  logic       busy, bc_tgl;
  logic [7:0] byte_count_hold;

  always_ff @(posedge ctrl_clk or negedge rst_n) begin
    if (!rst_n) begin
      intr_state_c1<='0; intr_state_c2<='0; busy_c1<=0; busy_c2<=0;
      bc_tgl_c1<=0; bc_tgl_c2<=0; bc_tgl_c3<=0; byte_count_ctrl<='0;
    end else begin
      intr_state_c1<=intr_state; intr_state_c2<=intr_state_c1;
      busy_c1<=busy;             busy_c2<=busy_c1;
      bc_tgl_c1<=bc_tgl; bc_tgl_c2<=bc_tgl_c1; bc_tgl_c3<=bc_tgl_c2;
      // byte_count_hold is multi-bit, so it is only sampled on the toggle edge
      // that announces it - never continuously.
      if (bc_tgl_c2 != bc_tgl_c3) byte_count_ctrl<=byte_count_hold;
    end
  end

  always_comb begin
    case (csr_addr)
      A_CTRL:       csr_rdata = {29'b0, bad_irq_ctrl, inject_ctrl, enable_ctrl};
      A_INTR_EN:    csr_rdata = {28'b0, intr_en_ctrl};
      A_INTR_STATE: csr_rdata = {28'b0, intr_state_c2};
      A_STATUS:     csr_rdata = {16'b0, byte_count_ctrl, 7'b0, busy_c2};
      A_ID:         csr_rdata = ID_VALUE;
      default:      csr_rdata = 32'b0;
    endcase
  end

  // ---------------------------------------------------------------------
  // dma_clk domain: control bit and command synchronizers
  // ---------------------------------------------------------------------
  logic enable_d1, enable_d2, inject_d1, inject_d2, bad_irq_d1, bad_irq_d2;
  logic [3:0] intr_en_d1, intr_en_d2;
  logic w1c_tgl_d1, w1c_tgl_d2, w1c_tgl_d3, cmd_tgl_d1, cmd_tgl_d2, cmd_tgl_d3;
  logic ovf_d1, ovf_d2, ovf_d3;
  logic w1c_apply, cmd_clear;
  logic [3:0] w1c_mask_d;

  always_ff @(posedge dma_clk or negedge rst_n) begin
    if (!rst_n) begin
      enable_d1<=0; enable_d2<=0; inject_d1<=0; inject_d2<=0; bad_irq_d1<=0; bad_irq_d2<=0;
      intr_en_d1<='0; intr_en_d2<='0; ovf_d1<=0; ovf_d2<=0; ovf_d3<=0;
      w1c_tgl_d1<=0; w1c_tgl_d2<=0; w1c_tgl_d3<=0;
      cmd_tgl_d1<=0; cmd_tgl_d2<=0; cmd_tgl_d3<=0; w1c_mask_d<='0;
    end else begin
      enable_d1<=enable_ctrl; enable_d2<=enable_d1;
      inject_d1<=inject_ctrl; inject_d2<=inject_d1;
      bad_irq_d1<=bad_irq_ctrl; bad_irq_d2<=bad_irq_d1;
      intr_en_d1<=intr_en_ctrl; intr_en_d2<=intr_en_d1;
      ovf_d1<=fifo_overflow; ovf_d2<=ovf_d1; ovf_d3<=ovf_d2;
      w1c_tgl_d1<=w1c_tgl_ctrl; w1c_tgl_d2<=w1c_tgl_d1; w1c_tgl_d3<=w1c_tgl_d2;
      cmd_tgl_d1<=cmd_tgl_ctrl; cmd_tgl_d2<=cmd_tgl_d1; cmd_tgl_d3<=cmd_tgl_d2;
      w1c_mask_d<=w1c_mask_ctrl;
    end
  end
  assign w1c_apply = (w1c_tgl_d2 != w1c_tgl_d3);
  assign cmd_clear = (cmd_tgl_d2 != cmd_tgl_d3);

  // ---------------------------------------------------------------------
  // Source side and the CDC FIFO
  // ---------------------------------------------------------------------
  logic [9:0] fifo_rdata; logic fifo_full, fifo_empty, fifo_pop;
  assign src_ready = !fifo_full;

  daq_async_fifo u_fifo(
    .wclk(src_clk), .wrst_n(rst_n), .w_en(src_valid && src_ready),
    .wdata({src_sop, src_eop, src_data}), .w_full(fifo_full),
    .rclk(dma_clk), .rrst_n(rst_n), .r_en(fifo_pop), .rdata(fifo_rdata), .r_empty(fifo_empty));

  always_ff @(posedge src_clk or negedge rst_n) begin
    if (!rst_n) fifo_overflow<=0;
    else if (src_valid && !src_ready) fifo_overflow<=1;
  end

  wire is_crc_beat = fifo_rdata[8];   // eop marks the CRC beat
  wire is_sop_beat = fifo_rdata[9];

  // ---------------------------------------------------------------------
  // DMA engine FSM
  // ---------------------------------------------------------------------
  typedef enum logic [2:0] { S_IDLE, S_ARMED, S_XFER, S_COMPLETE, S_ERROR } dma_state_e;
  dma_state_e state, state_n;

  logic beat_accepted, crc_consume, crc_mismatch;
  // Request is raised from FIFO occupancy alone - it must not depend on
  // dma_wready, or the handshake would deadlock against a target that only
  // raises ready in response to valid.
  assign dma_wvalid    = (state == S_XFER) && !fifo_empty && !is_crc_beat;
  assign beat_accepted = dma_wvalid && dma_wready;
  // The CRC beat never reaches the bus, so it is retired without a handshake.
  assign crc_consume   = (state == S_XFER) && !fifo_empty && is_crc_beat;
`ifdef MUTANT_POP_IGNORES_READY
  assign fifo_pop      = dma_wvalid || crc_consume;
`else
  assign fifo_pop      = beat_accepted || crc_consume;
`endif

  always_comb begin
    state_n = state;
    case (state)
      S_IDLE:     if (enable_d2) state_n = S_ARMED;
      S_ARMED:    if (!enable_d2) state_n = S_IDLE;
                  else if (!fifo_empty) state_n = S_XFER;
      S_XFER:     if (!enable_d2) state_n = S_IDLE;
                  else if (beat_accepted && dma_wresp_err) state_n = S_ERROR;
                  else if (crc_consume) state_n = S_COMPLETE;
      S_COMPLETE: if (cmd_clear || !enable_d2) state_n = S_IDLE;
      S_ERROR:    if (cmd_clear || !enable_d2) state_n = S_IDLE;
      default:    state_n = S_IDLE;
    endcase
  end

  always_ff @(posedge dma_clk or negedge rst_n) begin
    if (!rst_n) state <= S_IDLE;
    else if (cmd_clear) state <= S_IDLE;
    else state <= state_n;
  end
  assign busy = (state == S_ARMED) || (state == S_XFER);

  // ---------------------------------------------------------------------
  // Payload path, CRC-8 and target memory
  // ---------------------------------------------------------------------
  logic [7:0] mem[0:15];
  logic [4:0] wr_ptr;
  logic [7:0] crc_run;

  // CRC-8, polynomial 0x07, init 0x00 - a real check, not a placeholder. The
  // source appends crc8 of the payload as the eop beat and the engine compares.
  function automatic logic [7:0] crc8_next(input logic [7:0] crc, input logic [7:0] d);
    logic [7:0] c;
    c = crc ^ d;
    for (int i = 0; i < 8; i++) c = c[7] ? logic'(8'((c << 1)) ^ 8'h07) : 8'((c << 1));
    return c;
  endfunction

  // crc_inject corrupts the *computed* value, so the comparison below is what
  // actually fails - the fault is injected into a real check rather than
  // driving the error flag directly.
  assign crc_mismatch = crc_consume &&
                        ((crc_run ^ (inject_d2 ? 8'hFF : 8'h00)) != fifo_rdata[7:0]);

  assign dma_waddr = wr_ptr[3:0];
  assign dma_wdata = fifo_rdata[7:0];

  always_ff @(posedge dma_clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr<='0; crc_run<='0; byte_count_hold<='0; bc_tgl<=0;
    end else begin
      if (cmd_clear || state == S_IDLE) begin wr_ptr<='0; crc_run<='0; end
      if (beat_accepted) begin
        mem[wr_ptr[3:0]] <= fifo_rdata[7:0];
        wr_ptr <= wr_ptr + 1;
        crc_run <= crc8_next(is_sop_beat ? 8'h00 : crc_run, fifo_rdata[7:0]);
      end
      // Announce the final byte count exactly once per transfer, after it has
      // stopped changing - this is the payload half of the data+toggle
      // handshake that ctrl_clk samples.
      if (state == S_XFER && (crc_consume || (beat_accepted && dma_wresp_err))) begin
        byte_count_hold <= {3'b0, wr_ptr};
        bc_tgl <= ~bc_tgl;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Interrupt state: set in dma_clk, cleared by W1C from ctrl_clk
  // ---------------------------------------------------------------------
  logic [3:0] intr_set;
  assign intr_set[I_DONE] = crc_consume;
  assign intr_set[I_CRC]  = crc_mismatch;
  assign intr_set[I_BUS]  = beat_accepted && dma_wresp_err;
  // Rising edge, not level: fifo_overflow is sticky until reset, so a level
  // here would make the overflow interrupt permanently unclearable by W1C.
  assign intr_set[I_OVF]  = ovf_d2 && !ovf_d3;

  always_ff @(posedge dma_clk or negedge rst_n) begin
    if (!rst_n) intr_state <= '0;
    else if (cmd_clear) intr_state <= '0;
    // Set wins over clear on the same cycle: a cause that arrives while
    // software is clearing must not be silently dropped.
    else intr_state <= (intr_state & ~(w1c_apply ? w1c_mask_d : 4'b0)) | intr_set;
  end

  assign done       = intr_state[I_DONE];
  assign crc_error  = intr_state[I_CRC];
  assign bus_error  = intr_state[I_BUS];
  // bad_irq_demo is a deliberate fault-injection hook: it raises irq with no
  // pending enabled cause so p_irq_has_cause can be observed failing.
  assign irq        = |(intr_state & intr_en_d2) || bad_irq_d2;

  assign mem0=mem[0]; assign mem1=mem[1]; assign mem2=mem[2]; assign mem3=mem[3];

  // ---------------------------------------------------------------------
  // Simulation-only assertions. Excluded from the formal build: the bundled
  // slang frontend rejects `disable iff` and the temporal operators used here
  // (see samples/sample_test_2/formal/prim_fifo_sync.sby for the same tooling
  // gap). The equivalent formal properties live in formal/daq_status_formal.sv
  // and formal/daq_fifo_formal.sv, stated in the always-@* style yosys accepts.
  // ---------------------------------------------------------------------
`ifndef SYNTHESIS
  property p_no_write_when_full; @(posedge src_clk) disable iff(!rst_n) fifo_full |-> !src_ready; endproperty
  assert property(p_no_write_when_full);

  property p_irq_has_cause; @(posedge dma_clk) disable iff(!rst_n) irq |-> |intr_state; endproperty
  assert property(p_irq_has_cause);

  // Backpressure: a beat that goes to the bus is only retired on an accepted
  // handshake. The CRC beat never reaches the bus and is carved out.
  property p_no_pop_without_ready; @(posedge dma_clk) disable iff(!rst_n)
    (fifo_pop && !crc_consume) |-> dma_wready; endproperty
  assert property(p_no_pop_without_ready);

  // AXI-style stability: a request that is not accepted must be held with the
  // same address and data until it is. Software disabling the block or issuing
  // the clear command is a deliberate abort.
  //
  // enable_d2 is carved out on both sides of the edge on purpose. The FSM
  // aborts using enable as it was at the antecedent, but enable may be back up
  // by the consequent - formal found that exact one-cycle-low trace against an
  // earlier version of this property that only looked at the consequent side.
  property p_wvalid_held; @(posedge dma_clk) disable iff(!rst_n)
    (dma_wvalid && !dma_wready && enable_d2 && !cmd_clear)
    |=> (!enable_d2 || cmd_clear || (dma_wvalid && $stable(dma_waddr) && $stable(dma_wdata))); endproperty
  assert property(p_wvalid_held);

  // The bus is only driven from the transfer state.
  property p_wvalid_only_in_xfer; @(posedge dma_clk) disable iff(!rst_n) dma_wvalid |-> (state == S_XFER); endproperty
  assert property(p_wvalid_only_in_xfer);

  // FSM never lands outside its declared encoding.
  property p_fsm_legal; @(posedge dma_clk) disable iff(!rst_n)
    state inside {S_IDLE, S_ARMED, S_XFER, S_COMPLETE, S_ERROR}; endproperty
  assert property(p_fsm_legal);
`endif
endmodule
